const updateProjectDetails = `-- name: UpdateProjectDetails :exec
UPDATE projects SET
    name = $1,
    profile_id = $2,
    client_name = $3,
    order_id = $4,
    client_contact = $5,
    project_type_id = $6,
    scope = $7,
    agreed_price = $8::text::numeric,
    -- Moving to another profile takes that profile's share; otherwise the recorded one stays.
    platform_fee_percent = CASE WHEN profile_id IS DISTINCT FROM $2
        THEN coalesce((SELECT mp.fee_percent FROM marketplace_profiles mp WHERE mp.id = $2), platform_fee_percent)
        ELSE platform_fee_percent END,
    currency = $9,
    start_date = $10::text::date,
    deadline = $11::text::timestamptz,
    overdue_alert_at = CASE WHEN deadline IS DISTINCT FROM $11::text::timestamptz THEN NULL ELSE overdue_alert_at END,
    priority = $12,
    special_notes = $13,
    lock_version = lock_version + 1,
    last_activity_at = now(),
    updated_at = now()
WHERE projects.id = $14
`

type UpdateProjectDetailsParams struct {
	Name          *string    `json:"name"`
	ProfileID     *uuid.UUID `json:"profile_id"`
	ClientName    *string    `json:"client_name"`
	OrderID       *string    `json:"order_id"`
	ClientContact *string    `json:"client_contact"`
	ProjectTypeID *uuid.UUID `json:"project_type_id"`
	Scope         *string    `json:"scope"`
	AgreedPrice   *string    `json:"agreed_price"`
	Currency      string     `json:"currency"`
	StartDate     *string    `json:"start_date"`
	Deadline      *string    `json:"deadline"`
	Priority      string     `json:"priority"`
	SpecialNotes  *string    `json:"special_notes"`
	ID            uuid.UUID  `json:"id"`
}

// Writes every editable column; the service merges the patch first.
func (q *Queries) UpdateProjectDetails(ctx context.Context, arg UpdateProjectDetailsParams) error {
	_, err := q.db.Exec(ctx, updateProjectDetails,
		arg.Name,
		arg.ProfileID,
		arg.ClientName,
		arg.OrderID,
		arg.ClientContact,
		arg.ProjectTypeID,
		arg.Scope,
		arg.AgreedPrice,
		arg.Currency,
		arg.StartDate,
		arg.Deadline,
		arg.Priority,
		arg.SpecialNotes,
		arg.ID,
	)
	return err
}
